import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Accessibility","description":"Accessibility reference documentation","frontmatter":{"title":"Accessibility","description":"Accessibility reference documentation"},"headers":[],"relativePath":"knowledge/accessibility.md","filePath":"knowledge/accessibility.md","lastUpdated":1784485118000}'),n={name:"knowledge/accessibility.md"};function o(r,e,l,c,d,h){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h1><h1 id="accessibility-wcag-2-1-aa-—-knowledge-base" tabindex="-1">Accessibility (WCAG 2.1 AA) — Knowledge Base <a class="header-anchor" href="#accessibility-wcag-2-1-aa-—-knowledge-base" aria-label="Permalink to &quot;Accessibility (WCAG 2.1 AA) — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Web accessibility ensures that websites are usable by everyone, including people with disabilities. This knowledge base covers WCAG 2.1 AA compliance, semantic HTML, ARIA patterns, keyboard navigation, and testing strategies for Next.js applications with bilingual support.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="wcag-2-1-principles-pour" tabindex="-1">WCAG 2.1 Principles (POUR) <a class="header-anchor" href="#wcag-2-1-principles-pour" aria-label="Permalink to &quot;WCAG 2.1 Principles (POUR)&quot;">​</a></h3><p><strong>Perceivable</strong> — Information and UI components must be presentable to users in ways they can perceive.</p><ul><li>Text alternatives for non-text content</li><li>Captions and audio descriptions</li><li>Content adaptable to different presentations</li><li>Sufficient color contrast</li></ul><p><strong>Operable</strong> — UI components and navigation must be operable by all users.</p><ul><li>Keyboard accessible</li><li>Enough time to read and use content</li><li>No content that causes seizures</li><li>Navigable with assistive technology</li></ul><p><strong>Understandable</strong> — Information and UI operation must be understandable.</p><ul><li>Readable text content</li><li>Predictable web page behavior</li><li>Input assistance and error prevention</li></ul><p><strong>Robust</strong> — Content must be robust enough to be interpreted by assistive technologies.</p><ul><li>Compatible with current and future tools</li><li>Valid, parseable markup</li><li>Proper ARIA usage</li></ul><h3 id="semantic-html" tabindex="-1">Semantic HTML <a class="header-anchor" href="#semantic-html" aria-label="Permalink to &quot;Semantic HTML&quot;">​</a></h3><p>Using HTML elements for their intended purpose provides built-in accessibility:</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Good: semantic --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nav</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Main navigation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/about&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;About&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nav</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Bad: non-semantic --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nav&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onclick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">navigate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(&#39;/about&#39;)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;About&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="aria-accessible-rich-internet-applications" tabindex="-1">ARIA (Accessible Rich Internet Applications) <a class="header-anchor" href="#aria-accessible-rich-internet-applications" aria-label="Permalink to &quot;ARIA (Accessible Rich Internet Applications)&quot;">​</a></h3><p>ARIA attributes supplement HTML semantics when native elements are insufficient:</p><p><strong>Roles:</strong> Define what an element is (<code>role=&quot;dialog&quot;</code>, <code>role=&quot;tablist&quot;</code>) <strong>States:</strong> Describe current condition (<code>aria-expanded=&quot;true&quot;</code>, <code>aria-selected=&quot;false&quot;</code>) <strong>Properties:</strong> Define relationships (<code>aria-labelledby</code>, <code>aria-describedby</code>)</p><p><strong>Critical rule:</strong> If a native HTML element provides the semantics you need, use it instead of ARIA. ARIA is a supplement, not a replacement.</p><h3 id="keyboard-navigation" tabindex="-1">Keyboard Navigation <a class="header-anchor" href="#keyboard-navigation" aria-label="Permalink to &quot;Keyboard Navigation&quot;">​</a></h3><p>All interactive elements must be reachable and operable via keyboard:</p><ul><li><strong>Tab</strong> — Move forward through interactive elements</li><li><strong>Shift+Tab</strong> — Move backward</li><li><strong>Enter/Space</strong> — Activate buttons and links</li><li><strong>Arrow keys</strong> — Navigate within composite widgets (tabs, menus, listboxes)</li><li><strong>Escape</strong> — Close modals, dropdowns, and popups</li></ul><h3 id="focus-management" tabindex="-1">Focus Management <a class="header-anchor" href="#focus-management" aria-label="Permalink to &quot;Focus Management&quot;">​</a></h3><p>Visual focus indicators must be clearly visible. Focus must be managed when:</p><ul><li>Opening/closing modals (focus moves to modal, returns on close)</li><li>Navigating between pages (focus management with React Router)</li><li>Dynamic content updates (screen reader announcements)</li></ul><h3 id="color-contrast" tabindex="-1">Color Contrast <a class="header-anchor" href="#color-contrast" aria-label="Permalink to &quot;Color Contrast&quot;">​</a></h3><p>WCAG AA requires:</p><ul><li><strong>Normal text:</strong> Minimum 4.5:1 contrast ratio against background</li><li><strong>Large text (≥18pt or ≥14pt bold):</strong> Minimum 3:1 contrast ratio</li><li><strong>UI components and graphical objects:</strong> Minimum 3:1 contrast ratio</li></ul><h3 id="live-regions" tabindex="-1">Live Regions <a class="header-anchor" href="#live-regions" aria-label="Permalink to &quot;Live Regions&quot;">​</a></h3><p>Dynamic content updates must be announced to screen readers:</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-live</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;polite&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-atomic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Form submitted successfully</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><code>aria-live=&quot;polite&quot;</code> — Announces after current announcement completes</li><li><code>aria-live=&quot;assertive&quot;</code> — Interrupts current announcement</li><li><code>aria-atomic=&quot;true&quot;</code> — Announces the entire region, not just changes</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use semantic HTML elements</strong> — <code>nav</code>, <code>main</code>, <code>article</code>, <code>section</code>, <code>header</code>, <code>footer</code>, <code>button</code>, <code>a</code> provide built-in accessibility for free</li><li><strong>Add proper heading hierarchy</strong> — Use <code>h1</code> through <code>h6</code> in logical order; never skip levels; one <code>h1</code> per page</li><li><strong>Implement keyboard navigation for all components</strong> — Every interactive element must be focusable and operable with keyboard; test by unplugging your mouse</li><li><strong>Provide visible focus indicators</strong> — Never use <code>outline: none</code> without a replacement; custom focus styles must meet contrast requirements</li><li><strong>Use ARIA only when needed</strong> — Prefer native HTML semantics; add ARIA attributes only when HTML alone doesn&#39;t convey the meaning</li><li><strong>Test with screen readers</strong> — Use NVDA (Windows), VoiceOver (Mac), or TalkBack (Android) to verify your application is usable</li><li><strong>Add alt text to all meaningful images</strong> — Decorative images use <code>alt=&quot;&quot;</code>; informative images describe the content or function</li><li><strong>Ensure sufficient color contrast</strong> — Use tools like WebAIM Contrast Checker; don&#39;t rely solely on color to convey information</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>tabindex</code> greater than 0</strong> — Positive tabindex values create unpredictable tab order; use <code>tabindex=&quot;0&quot;</code> for focusable elements and <code>tabindex=&quot;-1&quot;</code> for programmatically focusable</li><li><strong>Divs and spans as buttons</strong> — <code>&lt;div onclick&gt;</code> or <code>&lt;span onClick&gt;</code> lack keyboard support, focusability, and semantics; use <code>&lt;button&gt;</code> elements</li><li><strong>Missing form labels</strong> — Inputs without associated labels are inaccessible; use <code>&lt;label htmlFor=&quot;id&quot;&gt;</code> or <code>aria-label</code></li><li><strong>Auto-playing media</strong> — Videos or audio that auto-play without user interaction trap screen reader users and cause discomfort</li><li><strong>Using color alone to convey meaning</strong> — &quot;Fields in red are required&quot; excludes colorblind users; add text labels or icons</li><li><strong>Focus trapping in wrong order</strong> — Modal focus trap must cycle through all focusable elements and not allow escape to background content</li><li><strong>Removing focus outlines</strong> — <code>outline: none</code> without replacement makes keyboard navigation impossible for sighted keyboard users</li><li><strong>Inaccessible custom dropdowns</strong> — Custom select components without proper ARIA roles, keyboard support, and screen reader announcements fail accessibility</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not adding <code>lang</code> attribute to html element</strong> — Screen readers need <code>lang=&quot;ar&quot;</code> or <code>lang=&quot;en&quot;</code> to use correct pronunciation and reading direction</li><li><strong>Skipping heading levels</strong> — Jumping from <code>h1</code> to <code>h4</code> confuses screen reader users who navigate by headings; maintain sequential order</li><li><strong>Missing skip navigation link</strong> — Add a &quot;Skip to main content&quot; link as the first focusable element to bypass repetitive navigation</li><li><strong>Inaccessible error messages</strong> — Error messages must be associated with their fields using <code>aria-describedby</code> and announced to screen readers</li><li><strong>Using <code>display: none</code> for offscreen content</strong> — Content hidden this way is removed from accessibility tree; use <code>aria-hidden=&quot;true&quot;</code> for visually hidden but accessible content</li><li><strong>Not testing with actual assistive technology</strong> — Automated tools catch only ~30% of issues; manual testing with screen readers is essential</li><li><strong>Ignoring RTL accessibility</strong> — Arabic content needs <code>dir=&quot;rtl&quot;</code> on the html element; keyboard navigation should respect reading direction</li><li><strong>Missing form validation accessibility</strong> — Error states must be communicated via <code>aria-invalid</code>, <code>aria-describedby</code>, and live regions, not just visual styling</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommendation</th></tr></thead><tbody><tr><td>New component</td><td>Start with semantic HTML; add ARIA only if semantics are insufficient</td></tr><tr><td>Modal/dialog</td><td>Use <code>&lt;dialog&gt;</code> element with proper focus trap and <code>aria-modal</code></td></tr><tr><td>Complex widget (tabs, tree)</td><td>Follow WAI-ARIA Authoring Practices patterns exactly</td></tr><tr><td>Form validation</td><td>Associate errors with fields via aria-describedby; announce via live region</td></tr><tr><td>Dynamic content update</td><td>Use aria-live region to announce changes</td></tr><tr><td>Loading states</td><td>Announce loading state to screen readers; use <code>aria-busy</code></td></tr><tr><td>Arabic/English site</td><td>Set <code>lang</code> and <code>dir</code> correctly; ensure RTL keyboard navigation works</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>WCAG 2.1 Guidelines: <a href="https://www.w3.org/WAI/WCAG21/quickref/" target="_blank" rel="noreferrer">https://www.w3.org/WAI/WCAG21/quickref/</a></li><li>WAI-ARIA Authoring Practices: <a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">https://www.w3.org/WAI/ARIA/apg/</a></li><li>WebAIM: <a href="https://webaim.org/" target="_blank" rel="noreferrer">https://webaim.org/</a></li><li>axe DevTools: <a href="https://www.deque.com/axe/" target="_blank" rel="noreferrer">https://www.deque.com/axe/</a></li><li>NVDA Screen Reader: <a href="https://www.nvaccess.org/download/" target="_blank" rel="noreferrer">https://www.nvaccess.org/download/</a></li><li>VoiceOver (built into macOS/iOS)</li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Next.js focus management:</strong> Use <code>useRef</code> and <code>element.focus()</code> for programmatic focus; manage focus on route changes with <code>useEffect</code></li><li><strong>Tailwind focus styles:</strong> Use <code>focus-visible:ring-2 focus-visible:ring-primary</code> for consistent focus indicators</li><li><strong>Testing automation:</strong> Add <code>@axe-core/react</code> for development-time accessibility linting; integrate into CI with <code>axe-core/playwright</code></li><li><strong>Arabic accessibility:</strong> Ensure <code>dir=&quot;rtl&quot;</code> is set; test that keyboard navigation works in RTL layout; verify screen reader reads Arabic correctly</li><li><strong>Performance impact:</strong> Accessibility improvements (semantic HTML, proper attributes) have zero negative performance impact and often improve it</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,48)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
